#!/usr/bin/env python3
"""gaia: the oracle and do-nothing controls. Generated by `--kind files`.

    python3 data/datasets/gaia/control.py --oracle
    python3 data/datasets/gaia/control.py --noop
    python3 data/datasets/gaia/control.py --oracle --platform
    python3 data/datasets/gaia/control.py --noop   --platform

`data/scaffolds/command_control.py` carries the algorithm, and it is kind-agnostic: what is
dataset-specific is `oracle_files(task)` in `data/datasets/gaia.py` -- and here that is the benchmark's
**released answer**, so gate 1 is cheap and proves only that the check is reachable.

**For an `exec` dataset the by-hand arm does not exist**: the verifier's paths are
container-absolute (`/check.py`, `/app/answer.txt`), so running its argv on the host cannot
work. The registration therefore passes `--platform`, and the arm that proves gates 1 and 2 is
`eval.run.runner.run_one` against the real container -- which is also the arm that would catch an
image or network mistake. `data/datasets/tau_bench.py` records the same situation and registers no
control at all; this is the version that at least runs the arm that means something.
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))

from data.scaffolds import command_control  # noqa: E402


if __name__ == "__main__":
    raise SystemExit(command_control.control_main("gaia", sys.argv[1:]))
